const TIMEOUT_THRESHOLD = 50;
const TIMEOUT_ERROR_CODE = 'TIMEOUT';

const tools = [
  {
    name: 'slow_operation',
    description: 'Performs a slow operation with an optional delay.',
    inputSchema: {
      type: 'object',
      properties: {
        request_id: { type: 'string' },
        delay_ms: { type: 'integer' },
      },
      required: ['request_id'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

export async function callTool(name, args = {}) {
  if (name !== 'slow_operation') {
    const err = new Error('Unknown tool');
    err.code = -32602;
    throw err;
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    const err = new Error('Invalid arguments');
    err.code = -32602;
    throw err;
  }

  if (args.request_id === undefined) {
    const err = new Error('Missing required field: request_id');
    err.code = -32602;
    throw err;
  }

  const allowed = new Set(Object.keys(tools[0].inputSchema.properties));
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      const err = new Error('Extra field not allowed: ' + key);
      err.code = -32602;
      throw err;
    }
  }

  if ('delay_ms' in args) {
    const delay = args.delay_ms;
    if (!Number.isInteger(delay)) {
      const err = new Error('delay_ms must be an integer');
      err.code = -32602;
      throw err;
    }
    if (delay < 0) {
      const err = new Error('delay_ms must not be negative');
      err.code = -32602;
      throw err;
    }
    if (delay > TIMEOUT_THRESHOLD) {
      const err = new Error('Operation timed out');
      err.code = TIMEOUT_ERROR_CODE;
      throw err;
    }
  }

  return {
    content: [
      { type: 'text', text: JSON.stringify({ request_id: args.request_id, status: 'completed' }) },
    ],
  };
}

